/**
 * Spoločná ICE konfigurácia – viac STUN serverov zlepšuje šance na úspešné spojenie.
 */
export const RTC_PEER_CONFIG = {
  iceServers: [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' }
  ],
  iceCandidatePoolSize: 10,
  bundlePolicy: 'max-bundle'
};

/**
 * Obmedzenie rozlíšenia šetrí CPU/batériu pri viacerých účastníkoch (mesh).
 */
const VIDEO_CONSTRAINTS_TRY = [
  {
    audio: { echoCancellation: true, noiseSuppression: true },
    video: {
      facingMode: 'user',
      width: { ideal: 960, max: 1280 },
      height: { ideal: 540, max: 720 },
      frameRate: { ideal: 24, max: 30 }
    }
  },
  {
    audio: true,
    video: {
      facingMode: 'user',
      width: { ideal: 640, max: 854 },
      height: { ideal: 480, max: 480 },
      frameRate: { ideal: 15, max: 24 }
    }
  },
  { audio: true, video: { facingMode: 'user' } },
  { audio: true, video: true }
];

/**
 * getUserMedia s postupnými fallbackmi; na mobiloch často pomôže rozdelenie audio + video.
 */
export async function getUserMediaWithFallback() {
  let lastError;
  for (const constraints of VIDEO_CONSTRAINTS_TRY) {
    try {
      return await navigator.mediaDevices.getUserMedia(constraints);
    } catch (err) {
      lastError = err;
    }
  }
  try {
    const audioOnly = await navigator.mediaDevices.getUserMedia({ audio: true });
    const videoOnly = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: 'user' }
    });
    return new MediaStream([
      ...audioOnly.getTracks(),
      ...videoOnly.getTracks()
    ]);
  } catch (err) {
    if (lastError) throw lastError;
    throw err;
  }
}

export function attachStreamToVideo(videoEl, stream) {
  if (!videoEl || !stream) return;
  videoEl.srcObject = stream;
  const play = () => {
    videoEl.play().catch(() => {});
  };
  play();
  requestAnimationFrame(play);
}
