import React, { useCallback, useEffect, useRef, useState } from 'react';
import { database, storage } from '../services/firebase';
import { ref, onValue, set, remove, update, get } from 'firebase/database';
import { ref as storageRef, uploadBytes, getDownloadURL, deleteObject } from 'firebase/storage';
import * as pdfjsLib from 'pdfjs-dist/legacy/build/pdf';

function PresentationPanel({ roomNumber, uid, displayName, isHost, participantRoster }) {
  const basePath = `webrtc/${roomNumber}/presentation`;
  const [pres, setPres] = useState(null);
  const [pdfDoc, setPdfDoc] = useState(null);
  const [viewerUrl, setViewerUrl] = useState('');
  const [localPage, setLocalPage] = useState(1);
  const [followPresenter, setFollowPresenter] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [pdfError, setPdfError] = useState(null);
  const [canvasRenderFailed, setCanvasRenderFailed] = useState(false);
  const [renderedPageUrl, setRenderedPageUrl] = useState('');
  const viewerPageInitRef = useRef(false);
  const renderTaskRef = useRef(null);

  useEffect(() => {
    const r = ref(database, basePath);
    return onValue(r, (snap) => {
      setPres(snap.val());
    });
  }, [basePath]);

  const pdfUrl = pres?.pdfUrl;
  const storagePath = pres?.storagePath;

  useEffect(() => {
    viewerPageInitRef.current = false;
  }, [pdfUrl]);
  const slideViewers = pres?.slideViewers && typeof pres.slideViewers === 'object' ? pres.slideViewers : {};
  const presenterUid = pres?.presenterUid;
  const isPresenter = Boolean(uid && presenterUid && presenterUid === uid);
  const canBrowseSlides = isPresenter || Boolean(uid && slideViewers[uid]);
  const currentPage = Math.max(1, Number(pres?.currentPage) || 1);
  const totalPages = Math.max(0, Number(pres?.totalPages) || 0);

  useEffect(() => {
    if (!pdfUrl && !storagePath) {
      setPdfDoc(null);
      setViewerUrl('');
      setPdfError(null);
      setCanvasRenderFailed(false);
      setRenderedPageUrl('');
      return undefined;
    }
    let cancelled = false;
    setPdfError(null);
    setCanvasRenderFailed(false);
    setRenderedPageUrl('');
    const loadPdf = async () => {
      try {
        const resolvedUrl = pdfUrl || (storagePath ? await getDownloadURL(storageRef(storage, storagePath)) : '');
        if (!resolvedUrl) {
          throw new Error('Chýba URL na PDF súbor.');
        }
        if (!cancelled) {
          setViewerUrl(resolvedUrl);
        }

        const task = pdfjsLib.getDocument({ url: resolvedUrl, withCredentials: false, disableWorker: true });

        const pdf = await task.promise;
        if (cancelled) return;
        setPdfDoc(pdf);
      } catch (e) {
        if (!cancelled) {
          console.error(e);
          setPdfError('Nepodarilo sa načítať PDF (skontroluj sieť alebo pravidlá Storage).');
        }
      }
    };
    loadPdf();
    return () => {
      cancelled = true;
      if (renderTaskRef.current) {
        renderTaskRef.current.cancel();
      }
    };
  }, [pdfUrl, storagePath, basePath]);

  useEffect(() => {
    if (!isPresenter || !pdfDoc) return;
    const n = pdfDoc.numPages;
    if (!n) return;
    update(ref(database, basePath), {
      totalPages: n,
      updatedAt: Date.now()
    }).catch((e) => {
      console.warn('Aktualizácia počtu strán:', e);
    });
  }, [isPresenter, pdfDoc, basePath]);

  useEffect(() => {
    if (!pdfDoc) return;
    const max = pdfDoc.numPages || 1;
    const pageFromState = isPresenter ? currentPage : localPage;
    const safePage = Math.min(Math.max(1, pageFromState), max);
    let cancelled = false;

    const renderCurrentPage = async () => {
      try {
        if (renderTaskRef.current) {
          renderTaskRef.current.cancel();
        }
        const page = await pdfDoc.getPage(safePage);
        if (cancelled) return;
        const viewport = page.getViewport({ scale: 1 });
        const targetWidth = Math.min(980, Math.max(360, viewport.width));
        const scale = targetWidth / viewport.width;
        const scaledViewport = page.getViewport({ scale });
        const tempCanvas = document.createElement('canvas');
        tempCanvas.width = Math.floor(scaledViewport.width);
        tempCanvas.height = Math.floor(scaledViewport.height);
        const context = tempCanvas.getContext('2d');
        if (!context) return;
        renderTaskRef.current = page.render({
          canvasContext: context,
          viewport: scaledViewport
        });
        await renderTaskRef.current.promise;
        if (!cancelled) {
          const blob = await new Promise((resolve) => tempCanvas.toBlob(resolve, 'image/png'));
          if (!blob) {
            throw new Error('Konverzia renderu PDF na obrázok zlyhala.');
          }
          const nextUrl = URL.createObjectURL(blob);
          setRenderedPageUrl((prev) => {
            if (prev) {
              URL.revokeObjectURL(prev);
            }
            return nextUrl;
          });
          setCanvasRenderFailed(false);
        }
      } catch (error) {
        if (error?.name !== 'RenderingCancelledException' && !cancelled) {
          console.error(error);
          setCanvasRenderFailed(true);
        }
      }
    };

    renderCurrentPage();
    return () => {
      cancelled = true;
      if (renderTaskRef.current) {
        renderTaskRef.current.cancel();
      }
    };
  }, [pdfDoc, isPresenter, currentPage, localPage]);

  useEffect(() => {
    return () => {
      if (renderedPageUrl) {
        URL.revokeObjectURL(renderedPageUrl);
      }
    };
  }, [renderedPageUrl]);

  useEffect(() => {
    if (canBrowseSlides && !isPresenter && pdfDoc && !viewerPageInitRef.current) {
      viewerPageInitRef.current = true;
      const max = pdfDoc.numPages || 1;
      setLocalPage(Math.min(Math.max(1, currentPage), max));
    }
  }, [canBrowseSlides, isPresenter, pdfDoc, currentPage]);

  useEffect(() => {
    if (canBrowseSlides && followPresenter && !isPresenter && pdfDoc) {
      const max = pdfDoc.numPages || 1;
      setLocalPage(Math.min(Math.max(1, currentPage), max));
    }
  }, [currentPage, followPresenter, canBrowseSlides, isPresenter, pdfDoc]);

  const setPresenterPage = useCallback(
    async (next) => {
      if (!isPresenter) return;
      const max = pdfDoc?.numPages || totalPages || 1;
      const safe = Math.min(Math.max(1, next), max);
      try {
        await update(ref(database, basePath), {
          currentPage: safe,
          updatedAt: Date.now()
        });
      } catch (e) {
        console.error(e);
      }
    },
    [pdfDoc, totalPages, isPresenter, basePath]
  );

  const handleUpload = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || file.type !== 'application/pdf') {
      alert('Vyber súbor PDF.');
      return;
    }
    if (!uid) return;
    setUploading(true);
    try {
      const snap = await get(ref(database, basePath));
      const existing = snap.val() || {};
      const prevPath = existing.storagePath;
      const path = `presentation_pdfs/${roomNumber}/${uid}_${Date.now()}.pdf`;
      const sRef = storageRef(storage, path);
      await uploadBytes(sRef, file, { contentType: 'application/pdf' });
      const url = await getDownloadURL(sRef);
      if (prevPath && prevPath !== path) {
        try {
          await deleteObject(storageRef(storage, prevPath));
        } catch (err) {
          console.warn('Starý PDF sa nepodarilo zmazať:', err);
        }
      }
      await set(ref(database, basePath), {
        pdfUrl: url,
        storagePath: path,
        presenterUid: uid,
        presenterName: displayName || 'Prezentujúci',
        currentPage: 1,
        totalPages: 0,
        updatedAt: Date.now(),
        slideViewers: existing.slideViewers && typeof existing.slideViewers === 'object' ? existing.slideViewers : {}
      });
    } catch (err) {
      console.error(err);
      alert('Nahrávanie PDF zlyhalo. Skontroluj pravidlá Firebase Storage.');
    } finally {
      setUploading(false);
    }
  };

  const handleRemovePresentation = async () => {
    if (!pres?.pdfUrl) return;
    const ok = window.confirm('Naozaj odstrániť PDF prezentáciu z meetingu?');
    if (!ok) return;
    try {
      if (pres.storagePath) {
        try {
          await deleteObject(storageRef(storage, pres.storagePath));
        } catch (err) {
          console.warn('Zmazanie súboru:', err);
        }
      }
      await remove(ref(database, basePath));
    } catch (err) {
      console.error(err);
      alert('Nepodarilo sa odstrániť prezentáciu.');
    }
  };

  const toggleSlideViewer = async (targetUid) => {
    if (!isHost || !targetUid) return;
    const path = `${basePath}/slideViewers/${targetUid}`;
    const snap = await get(ref(database, path));
    try {
      if (snap.exists()) {
        await remove(ref(database, path));
      } else {
        await set(ref(database, path), true);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const maxKnownPage = pdfDoc?.numPages || totalPages || 1;
  const viewerPage = Math.min(Math.max(1, isPresenter ? currentPage : localPage), maxKnownPage);
  const effectiveTotal = pdfDoc?.numPages || totalPages || 0;
  // Prefer signed download URL for long-lived inline embeds.
  const popupBaseUrl = pdfUrl || viewerUrl;
  const popupHref = popupBaseUrl
    ? `${popupBaseUrl}#page=${viewerPage}&zoom=page-fit&toolbar=1&navpanes=0`
    : '';
  const isShowingFallbackPreview = (!pdfDoc || canvasRenderFailed) && Boolean(popupHref);
  const openPdfInNewTab = () => {
    if (!popupHref) return;
    window.open(popupHref, '_blank', 'noopener,noreferrer');
  };

  useEffect(() => {
    // Retry canvas rendering when page changes.
    setCanvasRenderFailed(false);
  }, [viewerPage]);

  return (
    <div className="presentation-panel">
      <h3 className="presentation-title">📑 Prezentácia (PDF)</h3>
      <p className="presentation-hint">
        Pri zdieľaní obrazovky ostatní vidia len video. Ak chcete komisii alebo vybraným ľuďom umožniť
        listovať slidy dopredu/dozadu a vidieť celý počet strán, nahrajte{' '}
        <strong>rovnaký súbor PDF</strong> ako prezentujete (PowerPoint → Uložiť ako PDF) a host môže
        udeliť práva na prehliadanie.
      </p>

      <div className="presentation-toolbar">
        <label className="presentation-upload-label">
          <input
            type="file"
            accept="application/pdf"
            onChange={handleUpload}
            disabled={uploading || !uid}
            className="presentation-file-input"
          />
          <span className="presentation-upload-btn">
            {uploading ? '⏳ Nahrávam…' : '📤 Nahrať PDF prezentáciu'}
          </span>
        </label>
        {pres?.pdfUrl && (isPresenter || isHost) && (
          <button type="button" className="presentation-remove-btn" onClick={handleRemovePresentation}>
            🗑️ Odstrániť PDF
          </button>
        )}
      </div>

      {isHost && participantRoster.length > 0 && (
        <div className="presentation-host-acl">
          <h4>Host – práva na listovanie slidov</h4>
          <p className="presentation-acl-hint">
            Zaškrtni účastníkov, ktorí môžu samostatne listovať celú prezentáciu (dopredu/dozadu).
          </p>
          <ul className="presentation-acl-list">
            {participantRoster
              .filter((p) => p.uid !== presenterUid)
              .map((p) => (
              <li key={p.uid}>
                <label className="presentation-acl-item">
                  <input
                    type="checkbox"
                    checked={Boolean(slideViewers[p.uid])}
                    onChange={() => toggleSlideViewer(p.uid)}
                  />
                  <span>{p.displayName || p.uid}</span>
                  {p.uid === uid ? <span className="presentation-you"> (ty)</span> : null}
                </label>
              </li>
              ))}
          </ul>
        </div>
      )}

      {!pres?.pdfUrl && <p className="presentation-empty">Zatiaľ nie je nahraté žiadne PDF.</p>}

      {pres?.pdfUrl && (
        <div className="presentation-active">
          <div className="presentation-meta">
            <span>
              Prezentujúci: <strong>{pres.presenterName || '—'}</strong>
            </span>
            <span className="presentation-slide-count">
              Stránka {viewerPage}
              {effectiveTotal > 0 ? ` / ${effectiveTotal}` : ''}
              {isPresenter ? ' (tvoja pozícia sa zdieľa s miestnosťou)' : ''}
            </span>
          </div>

          {canBrowseSlides ? (
            <div className="presentation-viewer">
              {!isPresenter && (
                <div className="presentation-follow-row">
                  <label className="presentation-follow-label">
                    <input
                      type="checkbox"
                      checked={followPresenter}
                      onChange={(e) => setFollowPresenter(e.target.checked)}
                    />
                    Sledovať pozíciu prezentéra
                  </label>
                  <button
                    type="button"
                    className="control-btn on"
                    onClick={() => {
                      setFollowPresenter(true);
                      const max = pdfDoc?.numPages || effectiveTotal || 1;
                      setLocalPage(Math.min(Math.max(1, currentPage), max));
                    }}
                  >
                    ↩ Na slide prezentéra
                  </button>
                </div>
              )}

              <div className="presentation-nav">
                <button
                  type="button"
                  className="control-btn on"
                  disabled={viewerPage <= 1}
                  onClick={() => {
                    if (isPresenter) {
                      setPresenterPage(currentPage - 1);
                    } else {
                      setFollowPresenter(false);
                      setLocalPage((p) => Math.max(1, p - 1));
                    }
                  }}
                >
                  ← Predchádzajúci
                </button>
                <button
                  type="button"
                  className="control-btn on"
                  disabled={effectiveTotal > 0 && viewerPage >= effectiveTotal}
                  onClick={() => {
                    if (isPresenter) {
                      setPresenterPage(currentPage + 1);
                    } else {
                      setFollowPresenter(false);
                      const max = pdfDoc?.numPages || effectiveTotal || 1;
                      setLocalPage((p) => Math.min(max, p + 1));
                    }
                  }}
                >
                  Ďalší →
                </button>
                <button
                  type="button"
                  className="control-btn on"
                  disabled={!popupHref}
                  onClick={openPdfInNewTab}
                >
                  🔎 Otvoriť v novom okne
                </button>
              </div>

              <div className="presentation-canvas-wrap">
                {pdfError && !isShowingFallbackPreview && <p className="presentation-error">{pdfError}</p>}
                {pdfDoc && !canvasRenderFailed && renderedPageUrl && (
                  <img
                    src={renderedPageUrl}
                    alt={`PDF strana ${viewerPage}`}
                    className="presentation-canvas"
                  />
                )}
                {isShowingFallbackPreview && (
                  <div className="presentation-inline-fallback">
                    <p className="presentation-inline-hint">
                      Použitý záložný PDF náhľad.
                    </p>
                    <iframe
                      key={`pdf-inline-${viewerPage}`}
                      title="PDF inline preview"
                      src={popupHref}
                      className="presentation-iframe"
                    />
                  </div>
                )}
                {!popupHref && !renderedPageUrl && (
                  <p className="presentation-error">PDF náhľad sa nepodarilo zobraziť inline. Použi otvorenie v novom okne.</p>
                )}
              </div>
            </div>
          ) : (
            <p className="presentation-no-access">
              PDF je aktívne. Na samostatné listovanie slidov potrebuješ práva od hosta.
            </p>
          )}
        </div>
      )}
    </div>
  );
}

export default PresentationPanel;
